mapper.select:
SELECT
FROM `schedule` s LEFT JOIN `season` se ON s.season_id = se.id AND se.deleted = 0 LEFT JOIN `match` m ON se.match_id = m.id AND m.deleted = 0 WHERE s.deleted = 0
AND s.season_id = #{query.seasonId}
AND s.schedule_name LIKE CONCAT('%', #{query.scheduleName}, '%')
AND s.status = #{query.status}
AND s.location LIKE CONCAT('%', #{query.location}, '%')
ORDER BY s.start_time DESC, s.create_time DESC
LIMIT #{query.pageSize} OFFSET #{query.offset}

SELECT COUNT(*) FROM `schedule` s WHERE s.deleted = 0
AND s.season_id = #{query.seasonId}
AND s.schedule_name LIKE CONCAT('%', #{query.scheduleName}, '%')
AND s.status = #{query.status}
AND s.location LIKE CONCAT('%', #{query.location}, '%')

mapper.update:
UPDATE `schedule` SET deleted = 1, update_time = NOW() WHERE id IN
#{id}
AND deleted = 0
